package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevBranch string = "  "
var WsPrevAcct string = "    "
var WsBal decimal.Decimal = decimal.Zero
var WsBranchTot decimal.Decimal = decimal.Zero
var WsGrandTot decimal.Decimal = decimal.Zero
var WsSkipped int64 = 0
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var curRec LedgerRec

var inputLines []string
var inputIdx int

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func storeBal(d decimal.Decimal) decimal.Decimal {
	d = d.Truncate(2)
	c := d.Shift(2).Truncate(0).IntPart()
	mod := int64(1000000000) // 10^(7+2)
	c = c % mod
	return decimal.New(c, -2)
}

func storeTot(d decimal.Decimal) decimal.Decimal {
	d = d.Truncate(2)
	c := d.Shift(2).Truncate(0).IntPart()
	mod := int64(100000000000) // 10^(9+2)
	c = c % mod
	return decimal.New(c, -2)
}

func formatPicture(absCents int64, intDigits string, pat string, fracCents int64) string {
	// intDigits: zero-padded string of capacity (already modded)
	// pat: integer pattern including commas, with Z/9 placeholders
	nCap := len(intDigits)
	// map placeholder positions
	// collect placeholder indices in pat
	phIdx := []int{}
	for i, ch := range pat {
		if ch == 'Z' || ch == '9' {
			_ = i
			phIdx = append(phIdx, i)
		}
	}
	// find first nonzero in intDigits
	firstNZ := -1
	for i := 0; i < nCap; i++ {
		if intDigits[i] != '0' {
			firstNZ = i
			break
		}
	}
	patChars := []rune(pat)
	digits := []rune(intDigits)
	// determine suppression for each placeholder order
	suppressed := make([]bool, nCap)
	if firstNZ == -1 {
		for i := 0; i < nCap; i++ {
			// Z -> suppressed, 9 (last) -> not
			// determine if placeholder char is Z
			pc := patChars[phIdx[i]]
			if pc == 'Z' {
				suppressed[i] = true
			} else {
				suppressed[i] = false
			}
		}
	} else {
		for i := 0; i < nCap; i++ {
			pc := patChars[phIdx[i]]
			if pc == 'Z' && i < firstNZ {
				suppressed[i] = true
			} else {
				suppressed[i] = false
			}
		}
	}
	// build integer part string
	// need mapping from pat position to digit order
	res := make([]rune, len(patChars))
	pi := 0 // placeholder order index
	for k, ch := range patChars {
		if ch == 'Z' || ch == '9' {
			if suppressed[pi] {
				res[k] = ' '
			} else {
				res[k] = digits[pi]
			}
			pi++
		} else {
			// comma: space if all placeholders to left are suppressed
			allSup := true
			for j := 0; j < pi; j++ {
				if !suppressed[j] {
					allSup = false
					break
				}
			}
			if allSup {
				res[k] = ' '
			} else {
				res[k] = ch
			}
		}
	}
	_ = absCents
	_ = fracCents
	return string(res)
}

func splitAbs(v decimal.Decimal, capDigits int) (string, int64) {
	neg := v.IsNegative()
	av := v
	if neg {
		av = v.Neg()
	}
	av = av.Truncate(2)
	cents := av.Shift(2).Truncate(0).IntPart()
	intPart := cents / 100
	frac := cents % 100
	mod := int64(1)
	for i := 0; i < capDigits; i++ {
		mod *= 10
	}
	intPart = intPart % mod
	s := fmt.Sprintf("%0*d", capDigits, intPart)
	return s, frac
}

func moveAmtEd(v decimal.Decimal) string {
	intStr, frac := splitAbs(v, 5)
	intFmt := formatPicture(0, intStr, "ZZ,ZZ9", 0)
	return fmt.Sprintf("%s.%02d", intFmt, frac)
}

func moveBalEd(v decimal.Decimal) string {
	neg := v.IsNegative()
	sign := " "
	if neg {
		sign = "-"
	}
	intStr, frac := splitAbs(v, 7)
	intFmt := formatPicture(0, intStr, "Z,ZZZ,ZZ9", 0)
	return fmt.Sprintf("%s%s.%02d", sign, intFmt, frac)
}

func moveTotEd(v decimal.Decimal) string {
	neg := v.IsNegative()
	sign := " "
	if neg {
		sign = "-"
	}
	intStr, frac := splitAbs(v, 9)
	intFmt := formatPicture(0, intStr, "ZZZ,ZZZ,ZZ9", 0)
	return fmt.Sprintf("%s%s.%02d", sign, intFmt, frac)
}

func READPARA() {
	if inputIdx < len(inputLines) {
		line := inputLines[inputIdx]
		inputIdx++
		if len(line) < 14 {
			line = line + strings.Repeat(" ", 14-len(line))
		} else if len(line) > 14 {
			line = line[:14]
		}
		brBranch := line[0:2]
		brAcct := line[2:6]
		brType := line[6:7]
		amtField := line[7:14]
		var amt decimal.Decimal
		t := strings.TrimSpace(amtField)
		if t == "" {
			amt = decimal.Zero
		} else {
			// digits only; may contain spaces? remove spaces
			s := ""
			for _, ch := range amtField {
				if ch >= '0' && ch <= '9' {
					s += string(ch)
				} else if ch == ' ' {
					continue
				} else {
					s += string(ch)
				}
			}
			if s == "" {
				amt = decimal.Zero
			} else {
				var n int64
				_, _ = fmt.Sscanf(s, "%d", &n)
				// manual parse to avoid overflow issues with Sscanf
				n = 0
				for _, ch := range s {
					if ch >= '0' && ch <= '9' {
						n = n*10 + int64(ch-'0')
					}
				}
				amt = decimal.New(n, -2)
			}
		}
		curRec = LedgerRec{BrBranch: brBranch, BrAcct: brAcct, BrType: brType, BrAmt: amt}
	} else {
		WsEofFlag = "Y"
	}
}

func POSTPARA() {
	WsAmtEd = moveAmtEd(curRec.BrAmt)
	switch curRec.BrType {
	case "D":
		WsBal = storeBal(WsBal.Add(curRec.BrAmt))
		fmt.Printf("%s%s%s\n", curRec.BrAcct, " D ", WsAmtEd)
	case "C":
		WsBal = storeBal(WsBal.Sub(curRec.BrAmt))
		fmt.Printf("%s%s%s\n", curRec.BrAcct, " C ", WsAmtEd)
	default:
		WsSkipped = (WsSkipped + 1) % 100
		fmt.Printf("%s%s\n", curRec.BrAcct, " ? SKIPPED")
	}
}

func ACCTBREAKPARA() {
	WsBalEd = moveBalEd(WsBal)
	fmt.Printf("%s%s%s%s\n", "  ACCOUNT ", WsPrevAcct, " BALANCE:", WsBalEd)
	WsBranchTot = storeTot(WsBranchTot.Add(WsBal))
	WsBal = decimal.Zero
}

func BRANCHBREAKPARA() {
	WsTotEd = moveTotEd(WsBranchTot)
	fmt.Printf("%s%s%s%s\n", " BRANCH ", WsPrevBranch, " TOTAL:", WsTotEd)
	WsGrandTot = storeTot(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.Zero
}

func PROCESSPARA() {
	if isFirstRecord() {
		WsPrevBranch = curRec.BrBranch
		WsPrevAcct = curRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if curRec.BrBranch != WsPrevBranch {
			ACCTBREAKPARA()
			BRANCHBREAKPARA()
			WsPrevBranch = curRec.BrBranch
			WsPrevAcct = curRec.BrAcct
		} else {
			if curRec.BrAcct != WsPrevAcct {
				ACCTBREAKPARA()
				WsPrevAcct = curRec.BrAcct
			}
		}
	}
	POSTPARA()
	READPARA()
}

func GRANDPARA() {
	WsTotEd = moveTotEd(WsGrandTot)
	fmt.Printf("%s%s\n", "GRAND TOTAL:", WsTotEd)
	fmt.Printf("%s%02d\n", "SKIPPED: ", WsSkipped)
}

func main() {
	// init working storage (already set)
	WsPrevBranch = strings.Repeat(" ", 2)
	WsPrevAcct = strings.Repeat(" ", 4)

	f, err := os.Open("input.dat")
	if err != nil {
		// empty input -> treat as no records (COBOL OPEN would fail, but for tests treat empty)
		if os.IsNotExist(err) {
			inputLines = nil
		} else {
			fmt.Fprintln(os.Stderr, err.Error())
			os.Exit(1)
		}
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 1024*1024), 1024*1024)
		for sc.Scan() {
			// Scanner strips trailing \r?\n; keep other content as-is (do not trim)
			line := sc.Text()
			// remove trailing \r if present (CRLF)
			if strings.HasSuffix(line, "\r") {
				line = line[:len(line)-1]
			}
			inputLines = append(inputLines, line)
		}
		f.Close()
		if err := sc.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err.Error())
			os.Exit(1)
		}
	}

	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	if !isFirstRecord() {
		ACCTBREAKPARA()
		BRANCHBREAKPARA()
	}
	GRANDPARA()
}
